import java.util.Scanner;

public class FlightBooking {
    private String pName;
    private String flightNo;
    private int kms;
    private double fare;
    private double netAmount;

    public FlightBooking() {
        pName = "";
        flightNo = "";
        kms = 0;
        fare = 0.0;
        netAmount = 0.0;
    }

    public void input() {
        Scanner sc = new Scanner(System.in);
        System.out.print("Enter Passenger Name: ");
        pName = sc.nextLine();
        System.out.print("Enter Flight Number: ");
        flightNo = sc.nextLine();
        System.out.print("Enter Distance (in km): ");
        kms = sc.nextInt();
    }

    public void calculateFare() {
        if (kms <= 500) {
            fare = 2500.0;
        } else if (kms <= 1000) {
            fare = 2500.0 + (kms - 500) * 4.0;
        } else {
            fare = 2500.0 + (500 * 4.0) + (kms - 1000) * 3.50;
        }

        double airportTax = 0.12 * fare;
        netAmount = fare + airportTax;
    }

    public void display() {
        System.out.println("\n=========== AIREXPRESS E-TICKET ===========");
        System.out.println("Passenger Name     : " + pName);
        System.out.println("Flight Number      : " + flightNo);
        System.out.println("Flight Distance    : " + kms + " km");
        System.out.println("Base Fare          : Rs. " + fare);
        System.out.println("Airport Tax (12%)  : Rs. " + (0.12 * fare));
        System.out.println("Total Amount Paid  : Rs. " + netAmount);
        System.out.println("===========================================");
    }

    public static void main(String[] args) {
        FlightBooking ticket = new FlightBooking();
        ticket.input();
        ticket.calculateFare();
        ticket.display();
    }
}
```

