import java.util.Scanner;

public class BinarySearchBankAccounts {
    public static void main(String[] args) {
        Scanner in = new Scanner(System.in);
        final int N = 10;
        long[] accounts = new long[N];

        System.out.println("Enter " + N + " sorted Bank Account Numbers (ascending):");
        for (int i = 0; i < N; i++) {
            System.out.print("Account [" + (i + 1) + "]: ");
            accounts[i] = in.nextLong();
        }

        System.out.print("\nEnter Account Number to search: ");
        long target = in.nextLong();

        // Binary Search
        int low = 0, high = N - 1;
        int foundIndex = -1;

        while (low <= high) {
            int mid = low + (high - low) / 2;
            if (accounts[mid] == target) {
                foundIndex = mid;
                break;
            } else if (accounts[mid] < target) {
                low = mid + 1;
            } else {
                high = mid - 1;
            }
        }

        System.out.println();
        if (foundIndex != -1) {
            System.out.println("Account Number " + target + " found at position " + (foundIndex + 1) + ".");
        } else {
            System.out.println("Account Number " + target + " NOT FOUND in the bank registry.");
        }
    }
}
```

