import java.util.Scanner;

public class CaseToggleAndDigitMask {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        System.out.println("Enter a string:");
        String original = sc.nextLine();

        StringBuilder transformed = new StringBuilder();

        for (int i = 0; i < original.length(); i++) {
            char ch = original.charAt(i);

            if (Character.isUpperCase(ch)) {
                transformed.append(Character.toLowerCase(ch));
            } else if (Character.isLowerCase(ch)) {
                transformed.append(Character.toUpperCase(ch));
            } else if (Character.isDigit(ch)) {
                transformed.append('*');
            } else {
                transformed.append(ch);
            }
        }

        System.out.println("\nOriginal String   : " + original);
        System.out.println("Transformed String: " + transformed.toString());
    }
}
```

