import java.util.Scanner;

public class TechNumberCheck {
    public static void main(String[] args) {
        Scanner in = new Scanner(System.in);
        System.out.print("Enter a positive integer: ");
        int num = in.nextInt();

        // Count digits
        int temp = num;
        int count = 0;
        while (temp > 0) {
            count++;
            temp /= 10;
        }

        if (count % 2 != 0) {
            System.out.println(num + " has " + count + " digits (odd). It CANNOT be a Tech Number.");
            return;
        }

        int halfDigits = count / 2;
        int divisor = (int) Math.pow(10, halfDigits);

        int firstHalf = num / divisor;
        int secondHalf = num % divisor;

        int sum = firstHalf + secondHalf;
        int squareOfSum = sum * sum;

        System.out.println("\nDigits count = " + count);
        System.out.println("First Half   = " + firstHalf);
        System.out.println("Second Half  = " + secondHalf);
        System.out.println("Sum of Halves= " + sum);
        System.out.println("Square of Sum= " + squareOfSum);

        if (squareOfSum == num) {
            System.out.println("\n" + num + " is a TECH NUMBER.");
        } else {
            System.out.println("\n" + num + " is NOT a Tech Number.");
        }
    }
}
```

