import java.util.Scanner;

public class ScalarMatrixOperations {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        final int R = 3, C = 3;
        int[][] A = new int[R][C];
        int[][] B = new int[R][C];
        int[][] BT = new int[C][R];

        System.out.println("Enter elements for 3x3 matrix A:");
        for (int i = 0; i < R; i++) {
            for (int j = 0; j < C; j++) {
                A[i][j] = sc.nextInt();
            }
        }

        System.out.print("\nEnter scalar multiplier k: ");
        int k = sc.nextInt();

        // Scalar multiplication
        for (int i = 0; i < R; i++) {
            for (int j = 0; j < C; j++) {
                B[i][j] = k * A[i][j];
                BT[j][i] = B[i][j]; // Transpose of B
            }
        }

        System.out.println("\nOriginal Matrix A:");
        printMatrix(A);

        System.out.println("\nScaled Matrix B (A * " + k + "):");
        printMatrix(B);

        System.out.println("\nTranspose of Matrix B (B^T):");
        printMatrix(BT);
    }

    private static void printMatrix(int[][] mat) {
        for (int[] row : mat) {
            for (int val : row) {
                System.out.printf("%6d", val);
            }
            System.out.println();
        }
    }
}
```

