public class NumberSeries {
    // Overload 1: Alternating power series sum
    public void series(int x, int n) {
        double sum = 0.0;
        int sign = 1;

        System.out.println("Calculating alternating power series for x = " + x + ", n = " + n + ":");
        for (int i = 1; i <= n; i++) {
            double term = sign * Math.pow(x, i);
            sum += term;
            sign = -sign; // Alternate positive and negative
        }

        System.out.println("Sum of series S = " + (long) sum);
    }

    // Overload 2: Sequence n^3 - 1 for first 10 terms
    public void series() {
        System.out.println("Generating cubic sequence (i^3 - 1) for first 10 terms:");
        for (int i = 1; i <= 10; i++) {
            long term = (long) (Math.pow(i, 3) - 1);
            System.out.print(term + (i == 10 ? "" : ", "));
        }
        System.out.println();
    }

    public static void main(String[] args) {
        NumberSeries obj = new NumberSeries();

        // Test overload 1: x = 2, n = 5 -> 2 - 4 + 8 - 16 + 32 = 22
        obj.series(2, 5);

        System.out.println();
        // Test overload 2
        obj.series();
    }
}
```

